CREATE TYPE public.billing_status AS ENUM ('active','trial','past_due','suspended','cancelled','expired');
CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY role_self_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.billing_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, capacity integer NOT NULL UNIQUE CHECK(capacity>=5 AND capacity%5=0), monthly_amount bigint CHECK(monthly_amount>=0), published boolean NOT NULL DEFAULT true, price_revision integer NOT NULL DEFAULT 1, provider_monthly_price text, provider_annual_price text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.billing_plans TO authenticated;
GRANT ALL ON public.billing_plans TO service_role;
ALTER TABLE public.billing_plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY plans_read ON public.billing_plans FOR SELECT TO authenticated USING(published OR public.has_role(auth.uid(),'admin'));
INSERT INTO public.billing_plans(name,capacity) VALUES ('Starter',5),('Business',10),('Business+',15),('Pro',20),('Enterprise',25);
CREATE TABLE public.billing_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), currency text CHECK(currency~'^[A-Z]{3}$'), annual_discount_percent numeric CHECK(annual_discount_percent BETWEEN 0 AND 100), grace_days integer CHECK(grace_days BETWEEN 0 AND 90), provider text CHECK(provider IN ('stripe','paddle')), provider_ready boolean NOT NULL DEFAULT false, suspension_policy text NOT NULL DEFAULT 'block_new_only' CHECK(suspension_policy='block_new_only'), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.billing_settings TO authenticated;
GRANT ALL ON public.billing_settings TO service_role;
ALTER TABLE public.billing_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_read ON public.billing_settings FOR SELECT TO authenticated USING(true);
INSERT INTO public.billing_settings(id) VALUES(true);
CREATE TABLE public.subscriptions (user_id uuid PRIMARY KEY, plan_id uuid REFERENCES public.billing_plans(id), capacity integer NOT NULL DEFAULT 0 CHECK(capacity>=0 AND capacity%5=0), status public.billing_status NOT NULL DEFAULT 'trial', previous_status public.billing_status, legacy_access boolean NOT NULL DEFAULT false, enforce_capacity boolean NOT NULL DEFAULT true, interval text NOT NULL DEFAULT 'month' CHECK(interval IN ('month','year')), amount bigint CHECK(amount>=0), currency text CHECK(currency~'^[A-Z]{3}$'), provider_customer_id text, provider_subscription_id text UNIQUE, current_period_end timestamptz, grace_until timestamptz, cancel_at_period_end boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.subscriptions TO authenticated;
GRANT ALL ON public.subscriptions TO service_role;
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY subscription_read ON public.subscriptions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
INSERT INTO public.subscriptions(user_id,legacy_access,enforce_capacity) SELECT id,true,false FROM public.profiles UNION SELECT user_id,true,false FROM public.screens ON CONFLICT(user_id) DO NOTHING;
CREATE TABLE public.subscription_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, actor_id uuid, action text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.subscription_history TO authenticated;
GRANT ALL ON public.subscription_history TO service_role;
ALTER TABLE public.subscription_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY history_read ON public.subscription_history FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.payment_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, provider_id text NOT NULL UNIQUE, kind text NOT NULL CHECK(kind IN ('invoice','refund')), status text NOT NULL CHECK(status IN ('pending','paid','failed','refunded','void')), amount bigint NOT NULL, currency text NOT NULL, hosted_url text, paid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.payment_records TO authenticated;
GRANT ALL ON public.payment_records TO service_role;
ALTER TABLE public.payment_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY payments_read ON public.payment_records FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX payment_owner_date ON public.payment_records(user_id,created_at DESC);
CREATE TABLE public.billing_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, provider_event_id text NOT NULL, status text NOT NULL DEFAULT 'pending', occurred_at timestamptz, processed_at timestamptz, error_code text, UNIQUE(provider,provider_event_id));
GRANT ALL ON public.billing_events TO service_role;
ALTER TABLE public.billing_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.screen_entitlements (screen_id uuid PRIMARY KEY REFERENCES public.screens(id) ON DELETE CASCADE, user_id uuid NOT NULL, device_id uuid NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, revision bigint NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.screen_entitlements TO authenticated;
GRANT ALL ON public.screen_entitlements TO service_role;
ALTER TABLE public.screen_entitlements ENABLE ROW LEVEL SECURITY;
CREATE POLICY entitlement_read ON public.screen_entitlements FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX entitlement_owner_active ON public.screen_entitlements(user_id) WHERE active;
INSERT INTO public.screen_entitlements(screen_id,user_id,device_id,active) SELECT p.screen_id,p.user_id,p.device_id,p.status='paired' AND c.revoked_at IS NULL FROM public.pairing_sessions p JOIN public.screens s ON s.id=p.screen_id JOIN public.device_credentials c USING(device_id) WHERE p.user_id=s.user_id;
CREATE FUNCTION public.billing_lock_account(p_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('billing:'||p_user::text,0)); INSERT INTO public.subscriptions(user_id) VALUES(p_user) ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.billing_lock_account(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.billing_check_place(p_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.subscriptions; used integer; BEGIN PERFORM public.billing_lock_account(p_user); SELECT * INTO s FROM public.subscriptions WHERE user_id=p_user FOR UPDATE; IF s.status='suspended' OR (s.enforce_capacity AND (s.status NOT IN ('active','trial','past_due') OR (s.status='past_due' AND (s.grace_until IS NULL OR s.grace_until<=now())) OR (s.current_period_end IS NOT NULL AND s.current_period_end<=now()))) THEN RAISE EXCEPTION 'BILLING_INACTIVE'; END IF; IF NOT s.enforce_capacity THEN RETURN; END IF; SELECT count(*) INTO used FROM public.screen_entitlements WHERE user_id=p_user AND active; IF used>=s.capacity THEN RAISE EXCEPTION 'SCREEN_LIMIT:%',s.capacity; END IF; END $$;
REVOKE ALL ON FUNCTION public.billing_check_place(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.billing_new_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.subscriptions(user_id) VALUES(NEW.id) ON CONFLICT DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER billing_profile_created AFTER INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.billing_new_profile();
CREATE FUNCTION public.billing_track_pairing() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='paired' AND NEW.screen_id IS NOT NULL AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status OR OLD.screen_id IS DISTINCT FROM NEW.screen_id) THEN PERFORM public.billing_check_place(NEW.user_id); INSERT INTO public.screen_entitlements(screen_id,user_id,device_id) VALUES(NEW.screen_id,NEW.user_id,NEW.device_id); ELSIF NEW.status='revoked' AND NEW.screen_id IS NOT NULL THEN PERFORM public.billing_lock_account(NEW.user_id); UPDATE public.screen_entitlements SET active=false,revision=revision+1,updated_at=now() WHERE screen_id=NEW.screen_id; END IF; RETURN NEW; END $$;
CREATE TRIGGER billing_pairing_entitlement BEFORE INSERT OR UPDATE ON public.pairing_sessions FOR EACH ROW EXECUTE FUNCTION public.billing_track_pairing();
REVOKE INSERT ON public.screens FROM authenticated;
CREATE OR REPLACE FUNCTION public.claim_pairing_code_internal(p_code text,p_name text,p_location text,p_group uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ps public.pairing_sessions; sid uuid; allowed boolean; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF NOT EXISTS(SELECT 1 FROM public.device_pairing_config WHERE id=true AND enabled) THEN RAISE EXCEPTION 'Pairing disabled'; END IF; allowed=public.consume_device_limit('claim:user:'||auth.uid()::text,10,600); allowed=public.consume_device_limit('claim:global',100,600) AND allowed; IF NOT allowed THEN RETURN NULL; END IF; IF p_code !~ '^\d{6}$' OR length(trim(p_name)) NOT BETWEEN 1 AND 120 OR length(p_location)>240 THEN RETURN NULL; END IF; PERFORM public.billing_lock_account(auth.uid()); SELECT * INTO ps FROM public.pairing_sessions WHERE pairing_code=p_code FOR UPDATE; IF NOT FOUND OR ps.status<>'pending' OR ps.expires_at<=now() THEN RETURN NULL; END IF; IF EXISTS(SELECT 1 FROM public.device_credentials WHERE device_id=ps.device_id AND revoked_at IS NOT NULL) THEN RETURN NULL; END IF; IF p_group IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.groups WHERE id=p_group AND user_id=auth.uid()) THEN RETURN NULL; END IF; PERFORM public.billing_check_place(auth.uid()); INSERT INTO public.screens(user_id,name,pairing_code,location,group_id,status) VALUES(auth.uid(),trim(p_name),p_code,p_location,p_group,'pending') RETURNING id INTO sid; UPDATE public.pairing_sessions SET status='paired',user_id=auth.uid(),screen_id=sid,paired_at=now() WHERE id=ps.id; RETURN sid; END $$;
CREATE FUNCTION public.set_screen_entitlement(p_screen uuid,p_active boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.screen_entitlements; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; PERFORM public.billing_lock_account(auth.uid()); SELECT * INTO e FROM public.screen_entitlements WHERE screen_id=p_screen AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Forbidden'; END IF; IF p_active=e.active THEN RETURN; END IF; IF p_active THEN IF NOT EXISTS(SELECT 1 FROM public.pairing_sessions p JOIN public.device_credentials c USING(device_id) WHERE p.device_id=e.device_id AND p.status='paired' AND c.revoked_at IS NULL) THEN RAISE EXCEPTION 'DEVICE_REVOKED'; END IF; PERFORM public.billing_check_place(auth.uid()); END IF; UPDATE public.screen_entitlements SET active=p_active,revision=revision+1,updated_at=now() WHERE screen_id=p_screen; INSERT INTO public.subscription_history(user_id,actor_id,action,details) VALUES(auth.uid(),auth.uid(),CASE WHEN p_active THEN 'screen_reactivated' ELSE 'screen_deactivated' END,jsonb_build_object('screen_id',p_screen)); END $$;
REVOKE ALL ON FUNCTION public.set_screen_entitlement(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_screen_entitlement(uuid,boolean) TO authenticated;
CREATE FUNCTION public.billing_my_account() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.subscriptions; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; PERFORM public.billing_lock_account(auth.uid()); SELECT * INTO s FROM public.subscriptions WHERE user_id=auth.uid(); RETURN jsonb_build_object('subscription',to_jsonb(s)-'provider_customer_id'-'provider_subscription_id'-'previous_status','used',(SELECT count(*) FROM public.screen_entitlements WHERE user_id=auth.uid() AND active),'plans',COALESCE((SELECT jsonb_agg(to_jsonb(p)-'provider_monthly_price'-'provider_annual_price' ORDER BY capacity) FROM public.billing_plans p WHERE published),'[]'::jsonb),'settings',(SELECT to_jsonb(b) FROM public.billing_settings b WHERE id),'payments',COALESCE((SELECT jsonb_agg(t) FROM (SELECT id,kind,status,amount,currency,hosted_url,paid_at,created_at FROM public.payment_records WHERE user_id=auth.uid() ORDER BY created_at DESC LIMIT 100)t),'[]'::jsonb),'history',COALESCE((SELECT jsonb_agg(t) FROM (SELECT action,details,created_at FROM public.subscription_history WHERE user_id=auth.uid() ORDER BY created_at DESC LIMIT 50)t),'[]'::jsonb),'entitlements',COALESCE((SELECT jsonb_agg(jsonb_build_object('screen_id',screen_id,'active',active)) FROM public.screen_entitlements WHERE user_id=auth.uid()),'[]'::jsonb),'is_admin',public.has_role(auth.uid(),'admin')); END $$;
REVOKE ALL ON FUNCTION public.billing_my_account() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.billing_my_account() TO authenticated;
CREATE FUNCTION public.billing_admin_overview(p_page integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF p_page<0 OR p_page>100000 THEN RAISE EXCEPTION 'Invalid page'; END IF; RETURN jsonb_build_object('clients',COALESCE((SELECT jsonb_agg(t) FROM (SELECT s.user_id,p.email,p.full_name,p.org_name,s.plan_id,s.status,s.capacity,s.legacy_access,s.enforce_capacity,s.current_period_end,(SELECT count(*) FROM public.screen_entitlements e WHERE e.user_id=s.user_id AND e.active) AS used FROM public.subscriptions s LEFT JOIN public.profiles p ON p.id=s.user_id ORDER BY s.user_id LIMIT 25 OFFSET p_page*25)t),'[]'::jsonb),'total',(SELECT count(*) FROM public.subscriptions),'active',(SELECT count(*) FROM public.subscriptions WHERE status='active' AND NOT legacy_access),'past_due',(SELECT count(*) FROM public.subscriptions WHERE status='past_due'),'suspended',(SELECT count(*) FROM public.subscriptions WHERE status='suspended'),'screens',(SELECT count(*) FROM public.screen_entitlements WHERE active),'plans',COALESCE((SELECT jsonb_agg(to_jsonb(p)-'provider_monthly_price'-'provider_annual_price' ORDER BY capacity) FROM public.billing_plans p),'[]'::jsonb),'settings',(SELECT to_jsonb(b) FROM public.billing_settings b WHERE id)); END $$;
CREATE FUNCTION public.billing_admin_client(p_user uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN jsonb_build_object('screens',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'active',COALESCE(e.active,false),'last_seen',s.last_seen)) FROM public.screens s LEFT JOIN public.screen_entitlements e ON e.screen_id=s.id WHERE s.user_id=p_user),'[]'::jsonb),'payments',COALESCE((SELECT jsonb_agg(t) FROM (SELECT id,kind,status,amount,currency,hosted_url,created_at FROM public.payment_records WHERE user_id=p_user ORDER BY created_at DESC LIMIT 100)t),'[]'::jsonb),'history',COALESCE((SELECT jsonb_agg(t) FROM (SELECT action,details,created_at FROM public.subscription_history WHERE user_id=p_user ORDER BY created_at DESC LIMIT 50)t),'[]'::jsonb)); END $$;
CREATE FUNCTION public.billing_admin_save_plan(p_id uuid,p_name text,p_capacity integer,p_amount bigint,p_published boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF length(trim(p_name)) NOT BETWEEN 1 AND 80 OR p_capacity<5 OR p_capacity%5<>0 OR p_amount<0 THEN RAISE EXCEPTION 'Invalid plan'; END IF; IF p_id IS NULL THEN INSERT INTO public.billing_plans(name,capacity,monthly_amount,published) VALUES(trim(p_name),p_capacity,p_amount,p_published) RETURNING id INTO result; ELSE UPDATE public.billing_plans SET name=trim(p_name),capacity=p_capacity,monthly_amount=p_amount,published=p_published,price_revision=price_revision+1,provider_monthly_price=NULL,provider_annual_price=NULL,updated_at=now() WHERE id=p_id RETURNING id INTO result; IF result IS NULL THEN RAISE EXCEPTION 'Unknown plan'; END IF; END IF; RETURN result; END $$;
CREATE FUNCTION public.billing_admin_settings(p_currency text,p_discount numeric,p_grace integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; UPDATE public.billing_settings SET currency=p_currency,annual_discount_percent=p_discount,grace_days=p_grace,updated_at=now() WHERE id; END $$;
CREATE FUNCTION public.billing_admin_access(p_user uuid,p_action text,p_plan uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.subscriptions; p public.billing_plans; used integer; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; PERFORM public.billing_lock_account(p_user); SELECT * INTO s FROM public.subscriptions WHERE user_id=p_user FOR UPDATE; IF p_action='suspend' THEN UPDATE public.subscriptions SET previous_status=CASE WHEN status='suspended' THEN previous_status ELSE status END,status='suspended',updated_at=now() WHERE user_id=p_user; ELSIF p_action='reactivate' THEN IF s.status<>'suspended' THEN RETURN; END IF; UPDATE public.subscriptions SET status=COALESCE(previous_status,'trial'),previous_status=NULL,updated_at=now() WHERE user_id=p_user; ELSIF p_action='trial_plan' THEN IF s.provider_subscription_id IS NOT NULL THEN RAISE EXCEPTION 'PROVIDER_MANAGED'; END IF; SELECT * INTO p FROM public.billing_plans WHERE id=p_plan; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown plan'; END IF; SELECT count(*) INTO used FROM public.screen_entitlements WHERE user_id=p_user AND active; IF used>p.capacity THEN RAISE EXCEPTION 'CAPACITY_BELOW_USAGE'; END IF; UPDATE public.subscriptions SET plan_id=p.id,capacity=p.capacity,status='trial',legacy_access=false,enforce_capacity=true,amount=NULL,currency=NULL,current_period_end=NULL,grace_until=NULL,updated_at=now() WHERE user_id=p_user; ELSE RAISE EXCEPTION 'Invalid action'; END IF; INSERT INTO public.subscription_history(user_id,actor_id,action,details) VALUES(p_user,auth.uid(),p_action,jsonb_build_object('plan_id',p_plan)); END $$;
REVOKE ALL ON FUNCTION public.billing_admin_overview(integer),public.billing_admin_client(uuid),public.billing_admin_save_plan(uuid,text,integer,bigint,boolean),public.billing_admin_settings(text,numeric,integer),public.billing_admin_access(uuid,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.billing_admin_overview(integer),public.billing_admin_client(uuid),public.billing_admin_save_plan(uuid,text,integer,bigint,boolean),public.billing_admin_settings(text,numeric,integer),public.billing_admin_access(uuid,text,uuid) TO authenticated;
CREATE FUNCTION public.device_entitlement(p_device uuid,p_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; e public.screen_entitlements; BEGIN sid=public.device_screen(p_device,p_hash); SELECT * INTO e FROM public.screen_entitlements WHERE screen_id=sid; RETURN jsonb_build_object('version',1,'active',COALESCE(e.active,true),'revision',COALESCE(e.revision,0)); END $$;
REVOKE ALL ON FUNCTION public.device_entitlement(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.device_entitlement(uuid,text) TO service_role;
CREATE FUNCTION public.billing_immutable_screen_owner() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN RAISE EXCEPTION 'Screen owner is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_screen_owner BEFORE UPDATE OF user_id ON public.screens FOR EACH ROW EXECUTE FUNCTION public.billing_immutable_screen_owner();